ery protected workflow requires explicit permission.'],['Mutation audit','Successful create, update and delete actions are recorded.'],['Sensitive redaction','Passwords, tokens and secrets never enter audit payloads.'],['Encrypted backups','Database snapshots use application-level authenticated encryption.']] as $control)<div style="padding:12px;border-top:1px solid #edf0f5"><strong>✓ {{$control[0]}}</strong><div class="eyebrow">{{$control[1]}}</div></div>@endforeach</div><div class="card panel"><div class="panel-title"><h3>Recent backups</h3></div>@forelse($backups as $backup)<div style="padding:12px;border-top:1px solid #edf0f5"><strong>{{$backup->filename}}</strong><div class="eyebrow">{{number_format($backup->size/1024,1)}} KB · {{$backup->status}} · {{$backup->completed_at?->format('d M h:i A')}}</div><small style="font-family:monospace">{{substr($backup->checksum,0,18)}}…</small></div>@empty<p class="eyebrow">No backups recorded yet.</p>@endforelse</div></div><div class="card panel" style="margin-top:18px"><div class="panel-title"><h3>Immutable activity trail</h3><span class="eyebrow">{{$logs->total()}} audited actions</span></div><div style="overflow:auto"><table style="width:100%;border-collapse:collapse"><thead><tr style="text-align:left;color:#7b8499"><th style="padding:12px">Time</th><th>Event</th><th>Actor</th><th>IP address</th></tr></thead><tbody>@forelse($logs as $log)<tr style="border-top:1px solid #edf0f5"><td style="padding:12px">{{$log->created_at?->format('d M Y h:i A')}}</td><td style="font-family:monospace">{{$log->event}}</td><td>#{{$log->actor_id}}</td><td>{{$log->ip_address}}</td></tr>@empty<tr><td colspan="4" style="padding:30px;text-align:center;color:#8a92a5">No audited actions yet.</td></tr>@endforelse</tbody></table></div>{{$logs->links()}}</div>@endsection
